{"code": "import os
import pathlib
from PIL import Image

data_dir = pathlib.Path('data/web_scraped_small')
all_files = list(data_dir.glob('*/*'))
print(f"Total files: {len(all_files)}")
for f in all_files[:20]:
    print(f"{f.name} - suffix: {f.suffix}")

# Try to open each image and see if any fail
problematic = []
for f in all_files:
    try:
        with Image.open(f) as img:
            img.verify()
    except Exception as e:
        problematic.append((f, str(e)))

print(f"\nProblematic files: {len(problematic)}")
for f, err in problematic:
    print(f"{f}: {err}")"}

